// Build a single-file, GPU-free offline replay page from the latest benchmark
// results. Reviewers can open the generated HTML in any browser without
// Node.js, a model, or a GPU: every question's real OpenBridge answer, its
// sources, and the per-sentence verification are frozen into the page.
//
// The claims are NOT regenerated by a model here. The script re-runs the
// project's own deterministic retrieval + evidence window + verifyClaims
// (lib/*.mjs) over the saved answers, so the highlight matches what the live
// workbench produced.
//
// Usage: node scripts/build-offline-demo.mjs
// Output: dist/OpenBridge-离线演示.html

import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { chunkDocument, buildIndex, search } from '../lib/retrieval.mjs';
import { verifyClaims } from '../lib/verify.mjs';
import { detectIntent } from '../lib/intent.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const RESULTS = path.join(ROOT, 'results', 'latest-results.json');
const PROJECT = path.join(ROOT, 'data', 'sample-project.json');
const OUT = path.join(ROOT, 'dist', 'OpenBridge-离线演示.html');

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

// Mirror of server.mjs evidenceWindow (kept in sync intentionally).
function evidenceWindow(index, docId, best, maxChars) {
  const siblings = index.chunks.filter((c) => c.docId === docId).sort((a, b) => a.lineStart - b.lineStart);
  const position = siblings.findIndex((c) => c.lineStart === best.lineStart);
  if (position < 0) return { text: best.text, lineStart: best.lineStart, lineEnd: best.lineEnd };
  let start = position, end = position, total = siblings[position].text.length;
  // Grow outward, alternating sides so the best chunk stays centered (mirrors
  // server.mjs: preferring the front side starved content after the hit).
  while (total < maxChars && (start > 0 || end < siblings.length - 1)) {
    let extended = false;
    for (let attempt = 0; attempt < 2; attempt += 1) {
      const takeFront = (start + end + attempt) % 2 === 0;
      if (takeFront && start > 0) {
        const size = siblings[start - 1].text.length;
        if (total + size <= maxChars) { start -= 1; total += size; extended = true; break; }
      } else if (!takeFront && end < siblings.length - 1) {
        const size = siblings[end + 1].text.length;
        if (total + size <= maxChars) { end += 1; total += size; extended = true; break; }
      }
    }
    if (!extended) break;
  }
  return {
    text: siblings.slice(start, end + 1).map((c) => c.text).join('\n'),
    lineStart: siblings[start].lineStart, lineEnd: siblings[end].lineEnd
  };
}

// Mirror of server.mjs licenseWindow (kept in sync intentionally).
function licenseWindow(index, docId, best, query) {
  const siblings = index.chunks
    .filter((c) => c.docId === docId)
    .sort((a, b) => a.lineStart - b.lineStart);
  if (!siblings.length) return { text: best.text, lineStart: best.lineStart, lineEnd: best.lineEnd };
  const title = siblings[0];
  const aboutRedistribution = /redistribut|再分发|分发|distribut|修改后|义务|obligation/i.test(query);
  const sectionIdx = siblings.findIndex((c) => /Redistribution\.\s+You may (?:reproduce|make)|^\s*4\.\s+Redistribution/m.test(c.text));
  if (aboutRedistribution && sectionIdx >= 0) {
    const body = siblings.slice(sectionIdx, sectionIdx + 3);
    const last = body[body.length - 1];
    return {
      text: `${title.text}\n\n……（中间定义条款略，以下为与“再分发/分发”相关的条款）……\n\n${body.map((c) => c.text).join('\n')}`,
      lineStart: title.lineStart,
      lineEnd: last.lineEnd
    };
  }
  return evidenceWindow(index, docId, best, 4600);
}

function resolveEvidencePath(evidencePath) {
  if (!evidencePath) return null;
  const localPath = path.resolve(ROOT, evidencePath);
  const rel = path.relative(ROOT, localPath);
  if (rel === '..' || rel.startsWith('..' + path.sep) || path.isAbsolute(rel)) return null;
  return localPath;
}

const stateMeta = {
  grounded: { label: '有据', cls: 'grounded', tip: '引用标识、关键术语或用词与证据吻合' },
  paraphrase: { label: '语义改写', cls: 'paraphrase', tip: '词面未直接覆盖，需人工判断' },
  unsupported: { label: '无据', cls: 'unsupported', tip: '含具体事实但证据中找不到字面支撑' },
  miscited: { label: '错引', cls: 'miscited', tip: '引用了 A 资料，但该说法只在 B 资料中出现' },
  advice: { label: '建议', cls: 'neutral', tip: '建议性表述，不计入事实核验' },
  meta: { label: '说明', cls: 'neutral', tip: '对证据充分性的说明，不计入' }
};

function renderAnswerClaims(claims) {
  return claims.map((c) => {
    const meta = stateMeta[c.state] || stateMeta.meta;
    const reason = c.reason ? ` title="${esc(c.reason)}"` : '';
    return `<span class="claim ${meta.cls}"${reason}>${esc(c.text)}<sup>${meta.label}</sup></span>`;
  }).join('');
}

async function main() {
  const [resultsDoc, project] = await Promise.all([
    fs.readFile(RESULTS, 'utf8').then(JSON.parse),
    fs.readFile(PROJECT, 'utf8').then(JSON.parse)
  ]);

  // Rebuild the fixed-snapshot index exactly like the live server (trustDefault).
  const entries = [];
  for (const doc of project.documents) {
    let text = doc.content || '';
    if (doc.evidencePath) {
      const local = resolveEvidencePath(doc.evidencePath);
      if (local) { try { text = await fs.readFile(local, 'utf8'); } catch { /* use summary */ } }
    }
    entries.push({ docId: doc.id, type: doc.type, chunks: chunkDocument(text) });
  }
  const index = buildIndex(entries);

  const cases = [];
  for (const r of resultsDoc.results) {
    const intent = detectIntent(r.query);
    const hits = search(index, r.query, { limit: 3, intent, documents: project.documents });
    const docs = hits.map((hit) => {
      const doc = project.documents.find((d) => d.id === hit.docId);
      const win = doc?.type === 'LICENSE'
        ? licenseWindow(index, hit.docId, hit, r.query)
        : evidenceWindow(index, hit.docId, hit, doc?.type === 'TEST' ? 2200 : 4200);
      return { ...doc, evidenceText: win.text, lineStart: win.lineStart, lineEnd: win.lineEnd, score: hit.score };
    });

    const ragAnswer = r.rag?.answer || '';
    const verification = r.rag?.ai ? verifyClaims(ragAnswer, docs) : null;
    cases.push({
      id: r.id, query: r.query, expectedSource: r.expectedSource,
      baseline: r.baseline?.answer || '', rag: ragAnswer,
      ragAi: r.rag?.ai, model: r.rag?.model || '',
      latency: r.rag?.latencyMs ?? null,
      docs, verification
    });
  }

  // Aggregate figures for the header.
  const withVerif = cases.filter((c) => c.verification);
  const totalGrounded = withVerif.reduce((s, c) => s + c.verification.groundedClaims, 0);
  const totalFactual = withVerif.reduce((s, c) => s + c.verification.factualClaims, 0);
  const totalUnsupported = withVerif.reduce((s, c) => s + c.verification.unsupportedClaims + c.verification.misCitedClaims, 0);

  const navItems = cases.map((c, i) => `
    <button class="qnav" data-target="${i}">
      <span class="qnav-id">${esc(c.id)}</span>
      <span class="qnav-text">${esc(c.query)}</span>
    </button>`).join('');

  const panels = cases.map((c, i) => {
    const sources = c.docs.map((d) => `
      <details class="src" ${d === c.docs[0] ? 'open' : ''}>
        <summary><span class="src-id">${esc(d.id)}</span> ${esc(d.title)}
          <span class="src-lines">L${d.lineStart}-${d.lineEnd}</span></summary>
        <div class="src-meta">${esc(d.source || '')}</div>
        <pre class="src-text">${esc(d.evidenceText)}</pre>
      </details>`).join('');
    const v = c.verification;
    const verifBar = v ? `
      <div class="verif-bar">
        <span class="chip grounded">有据 ${v.groundedClaims}</span>
        <span class="chip paraphrase">改写 ${v.paraphrasedClaims}</span>
        <span class="chip ${v.unsupportedClaims + v.misCitedClaims ? 'danger' : 'ok'}">
          无据 ${v.unsupportedClaims}${v.misCitedClaims ? ` · 错引 ${v.misCitedClaims}` : ''}</span>
        <span class="chip neutral">事实句 ${v.factualClaims}</span>
      </div>` : '';
    const flagged = v ? [...v.unsupported, ...[]] : [];
    return `
    <article class="qpanel" data-panel="${i}">
      <div class="q-head">
        <h2>${esc(c.query)}</h2>
        <div class="q-meta">${esc(c.id)} · 模型 ${esc(c.model)} · 延迟 ${c.latency ? (c.latency / 1000).toFixed(1) + 's' : '—'}</div>
      </div>
      <div class="answer-block">
        <div class="block-label"><span class="dot rag-dot"></span>OpenBridge（检索 + 模型 + 逐句核验）</div>
        ${verifBar}
        <div class="answer-text">${v ? renderAnswerClaims(v.claims) : esc(c.rag)}</div>
      </div>
      <details class="baseline-block">
        <summary><span class="dot base-dot"></span>对照：通用模型单独作答（无检索证据，点击展开）</summary>
        <div class="answer-text baseline-text">${esc(c.baseline)}</div>
      </details>
      <div class="sources-block">
        <div class="block-label">检索到的证据（固定快照，可点击展开核对原文）</div>
        ${sources}
      </div>
    </article>`;
  }).join('\n');

  const html = `<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>OpenBridge 离线演示 · 12 题真实回放</title>
<style>
:root{--ink:#13233d;--muted:#71809a;--subtle:#98a6ba;--line:#e5eaf2;--surface:#fff;--canvas:#f3f6fb;--navy:#1b3d6d;--blue:#2e6cff;--blue-soft:#eaf1ff;--green:#1f9e6e;--green-bg:#eaf8f1;--amber:#b07a16;--amber-bg:#fdf4df;--red:#cf4d4d;--red-bg:#fdeeee;--shadow:0 14px 34px rgba(37,56,86,.08)}
*{box-sizing:border-box}
body{margin:0;background:var(--canvas);color:var(--ink);font-family:"Noto Sans SC","Microsoft YaHei","Segoe UI",sans-serif}
.replay-banner{background:linear-gradient(90deg,#1b3d6d,#2e6cff);color:#fff;padding:14px 34px;font-size:13px;line-height:1.55}
.replay-banner b{font-size:14px}
.replay-banner .sub{opacity:.86;display:block;margin-top:2px}
.topbar{height:70px;background:var(--surface);border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;padding:0 34px}
.brand-mark{width:36px;height:36px;border-radius:11px;background:var(--navy);color:#fff;display:grid;place-items:center;font-weight:800;font-size:13px;box-shadow:0 7px 15px rgba(27,61,109,.24)}
.brand-name{font-weight:800;font-size:18px}.brand-subtitle{color:var(--muted);font-size:12px;margin-top:2px}
.workspace{display:flex;min-height:calc(100vh - 118px)}
.sidebar{width:300px;flex:0 0 300px;background:#f8faff;border-right:1px solid var(--line);padding:18px 14px;overflow-y:auto;max-height:calc(100vh - 118px);position:sticky;top:0}
.legend{font-size:11px;color:var(--muted);line-height:1.9;background:#fff;border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-bottom:14px}
.legend b{display:block;color:var(--ink);margin-bottom:4px}
.qnav{width:100%;border:1px solid var(--line);background:#fff;border-radius:10px;padding:10px 12px;margin-bottom:7px;text-align:left;display:flex;gap:9px;align-items:baseline}
.qnav:hover{border-color:var(--blue);background:var(--blue-soft)}
.qnav-id{font-weight:800;color:var(--blue);font-size:12px;flex:0 0 auto}
.qnav-text{font-size:12.5px;color:var(--ink)}
.main{flex:1;padding:28px 36px 70px;max-width:1180px}
.summary{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px}
.stat{background:#fff;border:1px solid var(--line);border-radius:12px;padding:13px 18px;box-shadow:var(--shadow)}
.stat .v{font-size:24px;font-weight:850;letter-spacing:-.03em}.stat .k{color:var(--muted);font-size:11px;margin-top:3px}
.qpanel{background:var(--surface);border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow);padding:22px 24px;margin-bottom:20px}
.q-head h2{font-size:19px;margin:0 0 4px}.q-meta{color:var(--subtle);font-size:12px;margin-bottom:16px}
.block-label{font-size:12px;font-weight:800;color:var(--navy);margin:14px 0 8px;display:flex;align-items:center;gap:8px}
.dot{width:9px;height:9px;border-radius:50%;display:inline-block}.rag-dot{background:var(--green)}.base-dot{background:var(--subtle)}
.verif-bar{display:flex;gap:8px;flex-wrap:wrap;margin:6px 0 12px}
.chip{font-size:11.5px;font-weight:700;border-radius:999px;padding:4px 11px}
.chip.grounded{background:var(--green-bg);color:var(--green)}.chip.paraphrase{background:var(--amber-bg);color:var(--amber)}
.chip.danger{background:var(--red-bg);color:var(--red)}.chip.ok{background:var(--green-bg);color:var(--green)}.chip.neutral{background:#f1f4f9;color:var(--muted)}
.answer-text{font-size:13.5px;line-height:2.05;color:#27374f;white-space:pre-wrap}
.claim{border-radius:4px;padding:1px 1px;cursor:help}
.claim.grounded{background:var(--green-bg)}.claim.paraphrase{background:var(--amber-bg)}
.claim.unsupported,.claim.miscited{background:var(--red-bg);color:#a33;text-decoration:underline wavy var(--red)}
.claim.neutral{color:var(--muted)}
.claim sup{font-size:9px;font-weight:800;margin-left:1px;padding:0 2px;border-radius:3px}
.claim.grounded sup{color:var(--green)}.claim.paraphrase sup{color:var(--amber)}.claim.unsupported sup,.claim.miscited sup{color:var(--red)}.claim.neutral sup{color:var(--subtle)}
.baseline-block{margin-top:14px;border:1px dashed #d3dceb;border-radius:10px;padding:8px 14px;background:#fafbfe}
.baseline-block summary{cursor:pointer;font-size:12.5px;font-weight:800;color:var(--muted);display:flex;align-items:center;gap:8px}
.baseline-text{color:#5b6b84;margin-top:10px}
.sources-block{margin-top:16px}.src{border:1px solid var(--line);border-radius:10px;margin-bottom:8px;background:#fcfdff}
.src summary{cursor:pointer;padding:10px 13px;font-size:12.5px;font-weight:700;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.src-id{background:var(--blue-soft);color:var(--blue);border-radius:6px;padding:2px 7px;font-size:11px}
.src-lines{color:var(--subtle);font-weight:600;font-size:11px;margin-left:auto}
.src-meta{padding:0 13px 6px;font-size:11px;color:var(--blue);word-break:break-all}
.src-text{margin:0;padding:10px 13px 13px;font-size:11.5px;line-height:1.7;color:#41506a;white-space:pre-wrap;max-height:340px;overflow:auto;background:#f6f8fc;border-top:1px solid #eef1f7}
.foot{color:var(--subtle);font-size:11.5px;text-align:center;padding:16px 0 40px;line-height:1.7}
</style>
</head>
<body>
<div class="replay-banner">
  <b>离线回放 · 无需 GPU 或模型</b>
  <span class="sub">本页由 scripts/build-offline-demo.mjs 从 results/latest-results.json（${esc(resultsDoc.generatedAt)}）生成；回答为固定快照下的真实模型生成记录，逐句核验由项目自有代码重算，非实时调用、不可在此页提问。可复现方式：启动模型后运行 node scripts/benchmark.mjs。</span>
</div>
<div class="topbar">
  <div class="brand-mark">OB</div>
  <div><div class="brand-name">OpenBridge 开源桥</div><div class="brand-subtitle">Requests 固定提交 ${esc(project.project.snapshotCommit.slice(0,7))} · 12 题对照回放</div></div>
</div>
<div class="workspace">
  <aside class="sidebar">
    <div class="legend"><b>逐句核验图例</b>
      <span class="chip grounded">有据</span> 与证据吻合<br>
      <span class="chip paraphrase">语义改写</span> 需人工判断<br>
      <span class="chip danger">无据/错引</span> 幻觉风险，重点核对<br>
      <span class="chip neutral">说明/建议</span> 不计入事实核验
    </div>
    ${navItems}
  </aside>
  <main class="main">
    <div class="summary">
      <div class="stat"><div class="v">${cases.length}</div><div class="k">对照问题数</div></div>
      <div class="stat"><div class="v">${totalGrounded}/${totalFactual}</div><div class="k">事实句有据（逐句核验）</div></div>
      <div class="stat"><div class="v" style="color:${totalUnsupported ? 'var(--red)' : 'var(--green)'}">${totalUnsupported}</div><div class="k">无据/错引具体事实</div></div>
      <div class="stat"><div class="v">${esc(resultsDoc.model)}</div><div class="k">本地模型</div></div>
    </div>
    ${panels}
    <div class="foot">
      OpenBridge 开源协作智能体 · 离线演示页 · 证据来自 Requests 官方仓库固定提交 ${esc(project.project.snapshotCommit)}（Apache-2.0）<br>
      本页仅用于离线查看真实评测记录，回答与引用需结合证据原文核对，不构成法律意见。
    </div>
  </main>
</div>
<script>
document.querySelectorAll('.qnav').forEach((b)=>b.addEventListener('click',()=>{
  const p=document.querySelector('.qpanel[data-panel="'+b.dataset.target+'"]');
  if(p)p.scrollIntoView({behavior:'smooth',block:'start'});
}));
</script>
</body>
</html>`;

  await fs.mkdir(path.dirname(OUT), { recursive: true });
  await fs.writeFile(OUT, html, 'utf8');
  const kb = Math.round(Buffer.byteLength(html, 'utf8') / 1024);
  console.log(`离线演示页已生成：${path.relative(ROOT, OUT)}（${kb} KB，${cases.length} 题，有据 ${totalGrounded}/${totalFactual}，无据/错引 ${totalUnsupported}）`);
}

main().catch((err) => { console.error('生成失败：', err); process.exit(1); });
